#ifndef DH_PRIMES_H
#define DH_PRIMES_H

/* diffie-hellman key exchange moduli */
/* along with the (public) base and (private) exponent, the (public) modulus is used to derive the shared secret */
/* the shared secret is a 32-byte value unique to each client and is used to encrypt its metadata */
/* the modulus cannot be just any large number; it must be a suitable safe prime */
/* the client and server must use the same modulus; it is public and not meant to be secret */
/* the private exponent and the resulting shared secret are the secret values */
/* replace these with your own if you want */
/* larger moduli generally provide higher security, at the cost of slower key exchange */
/* these moduli are from https://2ton.com.au/safeprimes/ */

#define DH_MODULUS_2048_STR ""
#define DH_MODULUS_4096_STR ""
#define DH_MODULUS_8192_STR ""

#define DH_MODULUS_BITS 8192

#if DH_MODULUS_BITS == 2048
#define DH_MODULUS_STR DH_MODULUS_2048_STR
#define DH_EXPONENT_BITS 256
#elif DH_MODULUS_BITS == 4096
#define DH_MODULUS_STR DH_MODULUS_4096_STR
#define DH_EXPONENT_BITS 512
#elif DH_MODULUS_BITS == 8192
#define DH_MODULUS_STR DH_MODULUS_8192_STR
#define DH_EXPONENT_BITS 512
#else
#error "DH_MODULUS_BITS must be 2048, 4096, or 8192"
#endif

#endif
